def motif(kind):
    if kind=='host':return '<i class="m-host"></i><i class="m-host"></i><i class="m-host"></i>'
    if kind=='lens':return '<i class="m-lens"></i><i class="m-lens"></i><i class="m-lens"></i>'
    if kind=='archive':return '<i class="m-archive">1980</i><i class="m-archive">1984</i>'
    if kind=='islands':return '<i class="m-island"></i><i class="m-island"></i><i class="m-island"></i><i class="m-island"></i>'
    if kind=='growth':return ''.join(f'<i class="m-growth" style="--h:{h}%"></i>' for h in [18,26,32,40,48,56,68,77,90])
    if kind=='portrait':return '<i class="m-portrait">?</i><i class="m-portrait">?</i><i class="m-portrait">?</i>'
    if kind=='dynasty':return '<i class="m-dynasty"></i><i class="m-dynasty"></i><i class="m-dynasty"></i><i class="m-dynasty"></i>'
    if kind=='women':return '<i class="m-women"></i><i class="m-women"></i><i class="m-women"></i>'
    if kind=='museum':return '<i class="m-museum">1900</i><i class="m-museum">1920</i><i class="m-museum">1948</i>'
    return '<i class="m-sports"></i><i class="m-sports"></i><i class="m-sports"></i><i class="m-sports"></i>'
cards=''.join(f'''<a class="story {kind}" data-group="{'given' if int(num)<=6 else 'new'}" href="../{href}" style="--tint:{tint}"><img class="story-photo" src="../媒体/{kind}.jpg" alt="" loading="lazy"><div class="story-top"><span>专题 {num}</span><span>{escape(label)}</span></div><div class="story-bottom"><h3>{escape(title)}</h3><p>{escape(question)}</p><span class="enter">进入故事 <b>↗</b></span></div></a>''' for num,title,question,label,href,kind,tint in stories)

